-- Replace exact captured legacy descriptions only, preserving later manual edits.
CREATE TEMP TABLE curated_legacy_description_rewrites (
 product_code bigint PRIMARY KEY, expected_name text NOT NULL,
 old_md5 text NOT NULL, full_text text NOT NULL
) ON COMMIT DROP;
UPDATE products AS p SET description=c.full_text, updated_at=CURRENT_TIMESTAMP
FROM curated_legacy_description_rewrites AS c
WHERE p.product_code=c.product_code AND p.catalog_section='plants'
 AND p.name=c.expected_name AND md5(COALESCE(p.description,''))=c.old_md5;
