INSERT INTO curated_legacy_description_rewrites VALUES
  (114, 'Кактус Микс', 'dd952f33eb25f8349b0b79428e224e8c', 'Кактус из ассортимента в небольшом горшке. Вид, форма побегов и окраска экземпляра могут различаться. Кактусы накапливают влагу, но условия содержания зависят от происхождения: лесным видам требуется более мягкий свет и другой режим полива, чем пустынным.'),
  (115, 'Кактус (с цветками)', '15b0f6abfc32110c0138d1638543105d', 'Кактус из ассортимента с цветками. Вид и окраска конкретного экземпляра могут отличаться от фотографии; цветение не бывает непрерывным. Для точных рекомендаций по свету и зимовке определите вид по этикетке.'),
  (119, 'Калатея', 'ce3c749bb6fa2d06f2b358d2247fc886', 'Декоративнолистная калатея с выразительным рисунком листьев. Торговое название не уточняет вид или сорт, поэтому форма и окраска листьев зависят от экземпляра. Растение предпочитает тёплое место с рассеянным светом и влажным воздухом.'),
  (151, 'Монстера Медиум Сильвер', '350cffb7c0db62b12f48366b01d12b62', 'Монстера с серебристым оттенком листвы. «Медиум Сильвер» — торговое название, по которому нельзя уверенно определить ботанический вид или обещать определённую форму взрослых листьев. Для роста подойдёт опора и рыхлый субстрат.'),
  (164, 'Пальмы микс (Арека и Хамедорея)', 'b7b72352ad5c1ef3163f9a44adacf094', 'Под этим названием в ассортименте указаны арека и хамедорея. Конкретный состав позиции и вид пальмы следует подтвердить перед отправкой. Обеим группам подходят светлое место без жёсткого солнца и защита от холодных сквозняков.'),
  (166, 'Пеперомия', '1cbcd0593ed12751960f19eb08fa2126', 'Пеперомия — компактное комнатное растение с декоративной листвой. У видов этого рода листья отличаются формой, фактурой и окраской; точный вид товара не указан. Хорошо подходит для полки или подоконника с рассеянным светом.'),
  (181, 'Соланум (Паслен)', 'f09ec5991e68d909a59065fb96cf62f6', 'Декоративный паслён из рода Solanum. В зависимости от вида растение может образовывать яркие плоды, но их наличие у конкретного экземпляра не гарантировано. Плоды не предназначены для еды; держите растение вне доступа детей и животных.'),
  (182, 'Спатифиллум крашеный', '76c189cd11d103396adf4dc3d5a33960', 'Спатифиллум с декоративно окрашенным покрывалом соцветия. После окончания цветения новые покрывала могут иметь естественную окраску. У растения глянцевые листья, а лучшее место для него — тёплая комната с рассеянным светом.'),
  (187, 'Суккулент (микс)', 'b5aa9aac62413a485d937039f4cdc23f', 'Суккулент из ассортимента. Форма листьев, окраска и ботанический вид зависят от экземпляра. Большинство таких растений хранит запас влаги в листьях или стеблях; точный уход следует уточнить после определения вида.'),
  (189, 'Тилландсия микс', '15fec32f630fd3ead9517f6c751f01a0', 'Тилландсия из ассортимента. Размер, форма листьев и способ крепления зависят от вида. Многие тилландсии растут без обычной почвы и получают влагу через листья; после увлажнения им необходима хорошая вентиляция.'),
  (192, 'Фиалка в ассортименте', '8f8708ab4e9afcac9209ded17db0d77a', 'Комнатная фиалка из ассортимента с опушёнными листьями и цветками разных оттенков. Ботанически такие растения относятся к группе сенполий в роде Streptocarpus. Конкретная окраска и сорт зависят от поставки.'),
  (193, 'Фикус Али', '7dfa3018fb041b8bc8416a564853b931', 'Фикус «Али» с длинными узкими листьями. Это торговое название используется для узколистных фикусов; ботанический вид и сорт конкретного растения требуют сверки по этикетке. Деревце создаёт вертикальный акцент в светлой комнате.'),
  (195, 'Фикус Амстел', '46a9f561d61d9506d08ac222ba5c7856', 'Фикус из торговой линейки «Амстел» с узкими удлинёнными листьями. Конкретный сорт в названии товара не указан, поэтому форму и размер взрослой кроны не обещаем. Растение подходит для светлого помещения без холодных сквозняков.'),
  (206, 'Фикус Майя', 'b9062bc1512095e52ced8219869c3876', 'Декоративный фикус «Майя» в горшке. По одному торговому названию нельзя надёжно определить вид и форму роста конкретного экземпляра; их стоит сверить по этикетке и фото. При хорошем освещении и стабильном месте фикус сохраняет плотную листву.'),
  (211, 'Фикус Панда', '98bb32941190b39c5cea59d752cfa001', 'Декоративный фикус «Панда» с плотной кроной. Торговое название само по себе не подтверждает ботанический вид или сорт. Растение можно поддерживать формирующей обрезкой; форма конкретного экземпляра видна на его фотографии.'),
  (83, 'Бонсай Сосна', '7cca412d0de7ccea94a957b93ddf538f', 'Сосна, сформированная как бонсай в небольшом контейнере. Точный вид сосны не указан. Это уличное дерево с сезонным циклом, а не растение для постоянного содержания в комнате; небольшой горшок требует регулярной проверки влаги.'),
  (864, 'Бонсай Фисташка D15', 'dd7acf36c5268d6c783d76b0a1730c8a', 'Фисташковое дерево, сформированное как бонсай. Род Pistacia включает виды с разными требованиями к зимовке, поэтому без этикетки нельзя назвать растение комнатным или обещать определённый режим содержания. Вид экземпляра стоит подтвердить перед покупкой.');
